  const range=(id,label,min,max,value,step=1)=>`<label class="demo-field" for="${id}"><span>${label}<output id="${id}-value" for="${id}">${value}</output></span><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></label>`;
  const check=(id,label,checked=true)=>`<label class="demo-check"><input id="${id}" type="checkbox"${checked?' checked':''}>${label}</label>`;
